        assert_eq!(status, 400);
        assert!(
            html.contains("&lt;script&gt;alert(1)&lt;/script&gt;@evil&gt;.com"),
            "{html}"
        );
        assert!(!html.contains("<script>alert(1)"), "{html}");
        assert_eq!(read(&path), before);
